        return drone(lerp(x - 2.2, x, p) + drift, lerp(y - 1.5, y, p) - drift, z + bob, { mat: i === 0 ? 'sage' : 'sand', opacity: clamp(p * 2), size: 1.3, loose: p < 1 });
