      if (k > 0.6) parts.push(box(-1.3, 0.85, 0.3, 0.3, 0.3, 0.3 * ease.out(seg(k, 0.6, 0.85))));
      // route A bends round the high ground; route B goes straight in
      const A = [[-1.15, 1.0, 0.3], [-0.6, 0.35, 0.3], [-0.6, -0.1, 0.3], [0.1, 0.0, 0.3], [0.45, 0.45, 0.3]];
      const B = [[-1.0, 0.95, 0.3], [-0.2, 0.75, 0.3], [0.4, 0.6, 0.3]];
      const showA = t > 0 ? ease.inOut(seg(u, 0.1, 0.9)) : 0, fadeA = 1 - seg(u, 2.0, 2.4);
      const showB = ease.inOut(seg(u, 2.5, 3.3)), fadeB = 1 - seg(u, 4.5, 4.9);
      if (showA > 0 && fadeA > 0) parts.push(path(A, { dash: [0.8, 0.8], draw: showA, opacity: fadeA, offset: march(t, 5, [0.8, 0.8], 5) }));
      if (showB > 0 && fadeB > 0) parts.push(path(B, { dash: [0.8, 0.8], draw: showB, opacity: fadeB, offset: march(t, 5, [0.8, 0.8], 5) }));
      return parts;
