  fiber: {
    label: 'Fiber-optic drone',
    use: 'A drone on a fiber line ignores jamming; Leonidas still brings it down.',
    build: 1.6,
    idle: 5,
    still: 1.55,
    frame(k, t) {
      const parts = leonidas(-1.75, -0.65, ease.out(seg(k, 0, 0.25)), ease.out(seg(k, 0.15, 0.5)));
      // the spool its line runs from
      const spool = ease.out(seg(k, 0.3, 0.55));
      if (spool > 0) parts.push(cyl(2.05, 0.85, 0, 0.32, 0.36 * spool, 'z'));
      // it comes in on its line, a pulse drops it, the line falls slack; then
      // another climbs off the spool
      const u = secs(t, 5), S = [2.05, 0.85, 0.37];
      const launch = ease.out(seg(k, 0.55, 1));
      let p = [S[0], S[1], lerp(S[2], 1.45, launch)], op = launch, slack = 0;
      if (t > 0) {
        const come = ease.inOut(seg(u, 0, 1.6)), fall = ease.inOut(seg(u, 1.8, 2.4)), again = ease.out(seg(u, 3.4, 4.8));
        if (u < 3.2) {
          p = [lerp(S[0], 0.95, come), lerp(S[1], 0.15, come), lerp(1.45, 0.25, fall)];
          slack = fall;
          op = 1 - seg(u, 2.6, 3.1);
        } else {
          p = [S[0], S[1], lerp(S[2], 1.45, again)];
          op = seg(u, 3.4, 3.7);
        }
      }
      if (launch > 0 && op > 0.01) {
        const mid = [(S[0] + p[0]) / 2, (S[1] + p[1]) / 2, lerp(Math.max(S[2], p[2] - 0.35), 0.02, slack)];
        parts.push(path([[S[0], S[1], S[2]], mid, [p[0], p[1], p[2] + 0.02]], { width: 0.45, opacity: op }));
        parts.push(...drone(p[0], p[1], p[2], { opacity: op, size: 1.25 }));
      }
      const hit = seg(u, 1.3, 1.9);
      if (t > 0) parts.push(pulse(-1.15, 0.95, 0.05, 1.3, 0.25, 0.62, hit));
      return parts;
    },
  },

