  agile: {
    label: 'Agile combat defense',
    use: 'Packs up, moves and is defending again in minutes.',
    build: 1.6,
    idle: 9.6,
    still: 1.0,
    frame(k, t) {
      // a pod on its trailer opens and Leonidas rises from it; later it packs
      // away, moves along the route to a new position and deploys again
      const A = -1.4, B = 0.5, Y = -0.45, u = secs(t, 9.6), io = (a, b) => ease.inOut(seg(u, a, b));
      const x = lerp(A, B, io(2.8, 4.0) - io(7.6, 8.8));
      const d = t > 0 ? 1 - io(2.0, 2.8) + io(4.0, 4.8) - io(6.8, 7.6) + io(8.8, 9.6) : ease.inOut(seg(k, 0.45, 1));
      const on = seg(k, 0, 0.2);
      const parts = [path([[A + 0.6, Y + 0.45, 0], [B + 0.6, Y + 0.45, 0]], { dash: [0.8, 0.8], opacity: on * 0.8, layer: -1 })];
      parts.push(box(x - 0.1, Y, 0.18, 1.45, 0.9, 0.1, 'sand', { opacity: on }));
      for (const wx of [0.35, 0.95]) parts.push(cyl(x + wx, Y + 0.72, 0.17, 0.16, 0.2, 'y', 'sand', { opacity: on }));
      parts.push(box(x, Y + 0.05, 0.28, 1.25, 0.8, 0.55, 'sand', { opacity: on }));
      // the lid lifts and slides back; the array rises from inside
      const lid = ease.inOut(seg(d, 0, 0.5)), rise = ease.inOut(seg(d, 0.35, 1));
      if (d > 0.35) parts.push(box(x + 0.5, Y + 0.1, 0.83, 0.24, 0.7, 1.05 * rise, 'sage', { opacity: seg(d, 0.35, 0.6) }));
      parts.push(box(x - lid * 0.75, Y + 0.05, 0.83 + lid * 0.08, 1.25, 0.8, 0.06, 'sand', { opacity: on }));
      return parts;
    },
  },

