      for (const wx of [0.38, 0.92, 1.68, 2.22]) parts.push(cyl(x0 + wx, 0.98, 0.23, 0.22, 0.22, 'y', 'sand', { opacity: on }));
      if (rise > 0) parts.push(turned(x0 + 0.62, 0.55, 0.78 + bounce, 0.24, 0.72, 1.0 * rise, 0.45 * wave(t, 0.2), 'sage'));
