  security: {
    label: 'Security',
    use: 'Perimeters watched, and threats picked out before they arrive.',
    build: 1.8,
    idle: 4.4,
    still: 2.3,
    frame(k, t) {
      const up = (a, b) => ease.out(seg(k, a, b));
      // a fence along the far edges, a camera (sage) on its pole, panning; it
      // finds a drone outside the fence and brackets it
      const parts = [box(-1.4, -1.4, 0, 2.8, 2.8 * up(0, 0.2), 0.1)];
      const posts = [];
      for (let i = 0; i <= 2; i++) posts.push([1.3 - i * 1.3, -1.3]);
      for (let i = 1; i <= 2; i++) posts.push([-1.3, -1.3 + i * 1.3]);
      parts.push(...fence(posts, up(0.2, 0.55), 0.45));
      const pole = 1.0 * up(0.4, 0.7);
      parts.push(box(0.35, 0.35, 0.1, 0.12, 0.12, pole));
      // it looks out over the far corner, sweeping either side of it
      const look = -0.75 * Math.PI + 0.85 * wave(t, 1 / 4.4);
      const cam = ease.back(seg(k, 0.65, 0.9));
      if (cam > 0) parts.push(turned(0.41 + Math.cos(look) * 0.24, 0.41 + Math.sin(look) * 0.24, 0.1 + pole, 0.8 * cam, 0.4 * cam, 0.38 * cam, look, 'sage'));
      // the drone beyond the fence; bracketed while the camera is on it
      const dx = -1.85, dy = -0.15, dz = 1.2 + wave(t, 2 / 4.4) * 0.05;
      const toward = Math.atan2(dy - 0.41, dx - 0.41);
      const on = clamp(1 - Math.abs(Math.atan2(Math.sin(look - toward), Math.cos(look - toward))) / 0.35);
      if (k > 0.8) parts.push(...drone(dx, dy, dz, { size: 1.2, opacity: up(0.8, 1) }));
      if (on > 0 && k > 0.8) parts.push(corners(dx, dy, dz + 0.1, lerp(9, 6, on), { pair: true, opacity: on * up(0.8, 1), layer: 2 }));
      return parts;
    },
  },

